/**
 * Status of one local runtime component.
 */
export enum RuntimeCheckStatus {
    /**
     * Present and usable.
     */
    Ok,
    /**
     * Missing; `setup` can provision it.
     */
    Installable,
    /**
     * Missing or broken; needs user action.
     */
    Error,
    /**
     * Not used on this host.
     */
    NotApplicable,
    /**
     * Not reported.
     */
    Unknown
}

const FfiConverterTypeRuntimeCheckStatus = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = RuntimeCheckStatus;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return RuntimeCheckStatus.Ok;
                case 2: return RuntimeCheckStatus.Installable;
                case 3: return RuntimeCheckStatus.Error;
                case 4: return RuntimeCheckStatus.NotApplicable;
                case 5: return RuntimeCheckStatus.Unknown;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case RuntimeCheckStatus.Ok: return ordinalConverter.write(1, into);
                case RuntimeCheckStatus.Installable: return ordinalConverter.write(2, into);
                case RuntimeCheckStatus.Error: return ordinalConverter.write(3, into);
                case RuntimeCheckStatus.NotApplicable: return ordinalConverter.write(4, into);
                case RuntimeCheckStatus.Unknown: return ordinalConverter.write(5, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

