/**
 * Coarse lifecycle status.
 */
export enum SandboxStatus {
    /**
     * Running (or bound).
     */
    Running,
    /**
     * Suspended or scaled to zero.
     */
    Suspended,
    /**
     * Stopped.
     */
    Stopped,
    /**
     * Starting.
     */
    Provisioning,
    /**
     * Unknown; see `SandboxInfo.status_detail`.
     */
    Unknown
}

const FfiConverterTypeSandboxStatus = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = SandboxStatus;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return SandboxStatus.Running;
                case 2: return SandboxStatus.Suspended;
                case 3: return SandboxStatus.Stopped;
                case 4: return SandboxStatus.Provisioning;
                case 5: return SandboxStatus.Unknown;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case SandboxStatus.Running: return ordinalConverter.write(1, into);
                case SandboxStatus.Suspended: return ordinalConverter.write(2, into);
                case SandboxStatus.Stopped: return ordinalConverter.write(3, into);
                case SandboxStatus.Provisioning: return ordinalConverter.write(4, into);
                case SandboxStatus.Unknown: return ordinalConverter.write(5, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

/**
 * Portable lifecycle phase, the same words on every provider.
 */
export enum SandboxPhase {
    /**
     * Being created.
     */
    Provisioning,
    /**
     * Booting; readiness probes have not passed yet.
     */
    Starting,
    /**
     * Running and ready.
     */
    Ready,
    /**
     * Stopped or suspended.
     */
    Stopped
}

